mapper.select:
SELECT * FROM ( ( SELECT 'answer' AS type, a.answer_id AS targetId, a.question_title AS title, SUBSTRING(a.content, 1, 200) AS snippet, a.author_name AS authorName, '/view/zhihu/answer/' AS linkPrefix, a.created_time AS time, 'zhihu' AS source FROM zhihu_answer a
INNER JOIN content_tag_mapping tm ON tm.source='zhihu' AND tm.target_id=a.answer_id AND tm.target_type='answer' AND tm.tag_id IN #{tid}
WHERE 1=1
AND (a.question_title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND a.author_name = #{author}
AND 1=0
ORDER BY a.created_time DESC LIMIT #{limit} ) UNION ALL ( SELECT 'article' AS type, a.article_id AS targetId, a.title AS title, SUBSTRING(a.content, 1, 200) AS snippet, a.author_name AS authorName, '/view/zhihu/article/' AS linkPrefix, a.created_time AS time, 'zhihu' AS source FROM zhihu_article a
INNER JOIN content_tag_mapping tm ON tm.source='zhihu' AND tm.target_id=a.article_id AND tm.target_type='article' AND tm.tag_id IN #{tid}
WHERE 1=1
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND a.author_name = #{author}
AND 1=0
ORDER BY a.created_time DESC LIMIT #{limit} ) UNION ALL ( SELECT 'pin' AS type, p.pin_id AS targetId, '想法' AS title, SUBSTRING(p.content, 1, 200) AS snippet, p.author_name AS authorName, '/view/zhihu/pin/' AS linkPrefix, p.created_time AS time, 'zhihu' AS source FROM zhihu_pin p
INNER JOIN content_tag_mapping tm ON tm.source='zhihu' AND tm.target_id=p.pin_id AND tm.target_type='pin' AND tm.tag_id IN #{tid}
WHERE 1=1
AND p.content LIKE CONCAT('%', #{keyword}, '%')
AND p.author_name = #{author}
AND 1=0
ORDER BY p.created_time DESC LIMIT #{limit} ) UNION ALL ( SELECT 'guba_post' AS type, g.post_id AS targetId, g.title AS title, SUBSTRING(g.content, 1, 200) AS snippet, g.author_name AS authorName, '/view/guba/post/' AS linkPrefix, g.publish_time AS time, 'guba' AS source FROM guba_post g
INNER JOIN content_tag_mapping tm ON tm.source='guba' AND tm.target_id=g.post_id AND tm.target_type='post' AND tm.tag_id IN #{tid}
WHERE 1=1
AND (g.title LIKE CONCAT('%', #{keyword}, '%') OR g.content LIKE CONCAT('%', #{keyword}, '%'))
AND g.author_name = #{author}
AND 1=0
ORDER BY g.publish_time DESC LIMIT #{limit} ) ) AS combined ORDER BY time DESC
